    infantry:{hp:45,speed:45,range:105,damage:7,rate:.9,radius:9,type:'Infantry',icon:'♟'},
    scout:{hp:75,speed:65,range:125,damage:9,rate:.8,radius:12,type:'Recon',icon:'◈'},
    tank:{hp:145,speed:34,range:155,damage:20,rate:1.35,radius:15,type:'Armor',icon:'▰'},
    collector:{hp:110,speed:39,range:0,damage:0,rate:1,radius:13,type:'Harvester',icon:'⬡'}
  };
  const buildingStats = {hq:{hp:520,size:45,type:'Command Center',icon:'⌂'},power:{hp:180,size:30,type:'Power',icon:'ϟ'},barracks:{hp:240,size:34,type:'Infantry Production',icon:'▤'},factory:{hp:300,size:40,type:'Vehicle Production',icon:'▰'},defense:{hp:260,size:29,type:'Defense',icon:'⊕'}};
  const ui = {credits:$('credits'),income:$('income'),power:$('power'),army:$('army-count'),type:$('selection-type'),name:$('selection-name'),icon:$('selection-icon'),health:$('selection-health'),toast:$('toast'),start:$('start-screen'),pause:$('pause-screen'),end:$('end-screen'),objective:$('objective-card')};
  let width=0,height=0,dpr=1, faction='usa', playing=false,paused=false,over=false, credits=3500, time=0,last=0,toastTime=0, action='select', selected=null, placement=null, tab='structures', serial=0;
  let units=[],buildings=[],enemies=[],nodes=[],decor=[],shots=[],particles=[], camera={x:.5,y:.5,z:1}, enemyClock=20;
  const clamp=(n,a,b)=>Math.max(a,Math.min(b,n));
  const rand=(a,b)=>a+Math.random()*(b-a);
  const own=team=>team==='blue';
  function resize(){const r=canvas.getBoundingClientRect();width=r.width;height=r.height;dpr=Math.min(window.devicePixelRatio||1,2);canvas.width=Math.round(width*dpr);canvas.height=Math.round(height*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);draw();}
  function makeBuilding(kind,team,x,y){const s=buildingStats[kind],f=factionData[faction];return{id:'b'+(++serial),kind,team,x,y,hp:s.hp,max:s.hp,size:s.size,type:s.type,icon:s.icon,name:team==='blue'?(kind==='hq'?f.hq:f[kind]):kind==='hq'?'Enemy Command Center':'Hostile Outpost',range:kind==='hq'?125:kind==='defense'?160:0,damage:kind==='hq'?7:kind==='defense'?14:0,rate:kind==='hq'?1.5:1.1,cool:rand(.2,1),target:null};}
  function makeUnit(kind,team,x,y){const s=stats[kind],f=factionData[faction];return{id:'u'+(++serial),kind,team,x,y,hp:s.hp,max:s.hp,speed:s.speed,range:s.range,damage:s.damage,rate:s.rate,radius:s.radius,type:s.type,icon:s.icon,name:team==='blue'?f[kind]:kind==='tank'?'Hostile Armor':'Hostile Infantry',cool:rand(.1,.8),target:null,move:null,harvestNode:null,harvesting:false,carry:0};}
  function setup(){units=[];buildings=[];enemies=[];shots=[];particles=[];serial=0;credits=3500;time=0;enemyClock=24;camera={x:.5,y:.5,z:1};placement=null;selected=makeBuilding('hq','blue',.13,.53);buildings.push(selected);buildings.push(makeBuilding('hq','red',.88,.45));units.push(makeUnit('scout','blue',.19,.57),makeUnit('infantry','blue',.2,.62),makeUnit('infantry','blue',.18,.66));
    nodes=[];decor=[];let seed=29481;const random=()=>{seed=(seed*1664525+1013904223)>>>0;return seed/4294967296;};
    for(let i=0;i<28;i++)nodes.push({x:.22+random()*.56,y:.07+random()*.86,amount:900,active:true});
    for(let i=0;i<360;i++){const x=random(),y=random();if((x<.24&&y>.38&&y<.71)||(x>.77&&y>.3&&y<.61))continue;decor.push({x,y,r:2+random()*11,kind:random()<.67?'bush':'rock',tone:random(),rot:random()});}
    refreshUI();renderBuilds();}
  function toast(text){ui.toast.textContent=text;ui.toast.classList.add('show');toastTime=2.2;}
  function has(kind){return buildings.some(b=>b.team==='blue'&&b.kind===kind);}
  function available(kind){if(['power','barracks','defense'].includes(kind))return true;if(kind==='factory'||kind==='infantry')return has('barracks');if(['tank','scout','collector'].includes(kind))return has('factory');return false;}
  function refreshUI(){ui.credits.textContent=Math.floor(credits).toLocaleString();const collectors=units.filter(u=>u.team==='blue'&&u.kind==='collector').length;ui.income.textContent=collectors?`+$${collectors*600}/min`:'+$0/min';ui.army.textContent=String(units.filter(u=>u.team==='blue').length).padStart(2,'0');ui.power.textContent=has('power')?'STABLE':'LOW';ui.power.style.color=has('power')?'':'#e5a84c';
    if(selected){ui.type.textContent=selected.type||'UNIT';ui.name.textContent=selected.name;ui.icon.textContent=selected.icon||'⌖';ui.health.style.width=`${100*selected.hp/selected.max}%`;ui.health.style.background=selected.hp/selected.max<.3?'#df6451':'#c8f05b';}else{ui.type.textContent='BATTLEFIELD';ui.name.textContent='Select a unit or building';ui.icon.textContent='⌖';ui.health.style.width='0%';}
    document.querySelectorAll('.action-card').forEach(b=>b.classList.toggle('selected-action',b.dataset.action===action));document.querySelectorAll('.build-card').forEach(b=>b.disabled=credits<price[b.dataset.build]||!available(b.dataset.build)||!playing||paused||over);}
  function renderBuilds(){const list=$('build-list'),f=factionData[faction];let items=tab==='structures'?[['power',f.power,'Power supply'],['barracks',f.barracks,'Train infantry'],['factory',f.factory,'Build vehicles']]:tab==='units'?[['infantry',f.infantry,'Rifle infantry'],['scout',f.scout,'Fast recon'],['tank',f.tank,'Main battle tank'],['collector',f.collector,'Harvest supplies']]:[['defense',f.defense,'Automated perimeter gun']];$('build-category').textContent=tab.toUpperCase();list.innerHTML=items.map(([key,label,sub])=>`<button class="build-card" data-build="${key}"><span class="unit-art ${key}-art">${stats[key]?.icon||buildingStats[key]?.icon}</span><span class="build-copy"><b>${label}</b><small>${sub} · $${price[key]}</small></span><span class="build-price">${price[key]}</span></button>`).join('');list.querySelectorAll('.build-card').forEach(b=>b.onclick=()=>beginBuild(b.dataset.build));refreshUI();}
  function beginBuild(kind){if(!playing||paused||over)return;if(credits<price[kind]){toast('NOT ENOUGH SUPPLIES');return;}if(!available(kind)){toast(kind==='factory'?'BUILD A BARRACKS FIRST':'BUILD A WAR FACTORY FIRST');return;}credits-=price[kind];if(stats[kind]){const source=buildings.find(b=>b.team==='blue'&&((kind==='infantry'&&b.kind==='barracks')||(kind!=='infantry'&&b.kind==='factory')))||buildings.find(b=>b.team==='blue'&&b.kind==='hq');const u=makeUnit(kind,'blue',source.x+.04,source.y+.03);u.move={x:source.x+.09,y:source.y+.08};units.push(u);toast(`${u.name.toUpperCase()} DEPLOYED`);}else{placement=kind;toast(`SELECT AN OPEN LOCATION FOR ${factionData[faction][kind].toUpperCase()}`);}refreshUI();}
  function toScreen(x,y){return{x:(x-camera.x)*camera.z+.5,y:(y-camera.y)*camera.z+.5};}
  function toWorld(x,y){return{x:(x/width-.5)/camera.z+camera.x,y:(y/height-.5)/camera.z+camera.y};}
  function distance(a,b){const p=toScreen(a.x,a.y),q=toScreen(b.x,b.y);return Math.hypot((p.x-q.x)*width,(p.y-q.y)*height);}

