  function drawNode(n){if(!n.active)return;const p=toScreen(n.x,n.y),x=p.x,y=p.y;ctx.fillStyle='#554e39';ctx.beginPath();ctx.ellipse(x,y,.023,.013,-.2,0,Math.PI*2);ctx.fill();ctx.fillStyle='#d9ad54';for(let i=0;i<5;i++){ctx.beginPath();ctx.arc(x-.014+i*.007,y+Math.sin(i)*.005,.004,0,Math.PI*2);ctx.fill();}ctx.strokeStyle='#e6c46b88';ctx.lineWidth=.0012;ctx.beginPath();ctx.arc(x,y,.03,0,Math.PI*2);ctx.stroke();}
  function drawBuilding(b){const p=toScreen(b.x,b.y),x=p.x,y=p.y,s=b.size/width*camera.z;ctx.save();ctx.fillStyle=b.team==='blue'?factionData[faction].color:'#cc6451';ctx.globalAlpha=.2;ctx.beginPath();ctx.ellipse(x,y+s*.5,s*1.6,s*.38,0,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1;
    if(b.kind==='hq'){ctx.fillStyle='#252e29';ctx.fillRect(x-s*1.3,y-s*.72,s*2.6,s*1.44);ctx.fillStyle=b.team==='blue'?'#747f70':'#78624e';ctx.fillRect(x-s,y-s*.58,s*2,s*1.16);ctx.fillStyle='#353e36';ctx.fillRect(x-s*.72,y-s*.88,s*1.38,s*.5);ctx.fillStyle='#a1a48b';ctx.fillRect(x-s*.62,y-s*.8,s*.85,s*.24);ctx.fillStyle=b.team==='blue'?factionData[faction].light:'#df7355';ctx.fillRect(x+s*.36,y-s*.44,s*.56,s*.88);ctx.fillRect(x-s*.08,y-s*1.05,s*.045,s*.47);}else{ctx.fillStyle='#30372e';ctx.fillRect(x-s*1.1,y-s*.68,s*2.2,s*1.36);ctx.fillStyle=b.team==='blue'?'#78816a':'#866653';ctx.fillRect(x-s*.86,y-s*.5,s*1.72,s);ctx.fillStyle=b.team==='blue'?factionData[faction].light:'#e18c59';ctx.fillRect(x-s*.18,y-s*.83,s*.36,s*.28);ctx.fillStyle='#343c34';for(let i=0;i<3;i++)ctx.fillRect(x-s*.6+i*s*.48,y+s*.13,s*.23,s*.28);}
    if(b===selected){ctx.strokeStyle='#e2f781';ctx.lineWidth=.002;ctx.setLineDash([.009,.008]);ctx.strokeRect(x-s*1.42,y-s*1.14,s*2.84,s*2.3);ctx.setLineDash([]);}healthBar(b,x,y-s*1.25,s*2.4);ctx.restore();}
