    if(u===selected){ctx.strokeStyle='#e2f781';ctx.lineWidth=.002;ctx.beginPath();ctx.ellipse(x,y+r*.66,r*1.4,r*.5,0,0,Math.PI*2);ctx.stroke();}healthBar(u,x,y-r*1.0,r*2.3);
    if(u.move){ctx.strokeStyle='#d7ef81aa';ctx.lineWidth=.0012;ctx.setLineDash([.008,.008]);ctx.beginPath();ctx.moveTo(x,y);const m=toScreen(u.move.x,u.move.y);ctx.lineTo(m.x,m.y);ctx.stroke();ctx.setLineDash([]);ctx.fillStyle='#d7ef81';ctx.beginPath();ctx.arc(m.x,m.y,.004,0,Math.PI*2);ctx.fill();}}
  function healthBar(a,x,y,w){if(a.hp===a.max)return;ctx.fillStyle='#20251f';ctx.fillRect(x-w/2,y,w,.006);ctx.fillStyle=a.team==='red'?'#dd7557':factionData[faction].light;ctx.fillRect(x-w/2,y,w*clamp(a.hp/a.max,0,1),.006);}
  function drawShots(){for(const s of shots){const t=1-s.life/s.max,p=toScreen(s.x+(s.target.x-s.x)*t,s.y+(s.target.y-s.y)*t);ctx.fillStyle=s.color;ctx.beginPath();ctx.arc(p.x,p.y,.0035,0,Math.PI*2);ctx.fill();}}
  function drawParticles(){for(const p of particles){const q=toScreen(p.x,p.y);ctx.globalAlpha=clamp(p.life/p.max,0,1);ctx.fillStyle=p.color;ctx.beginPath();ctx.arc(q.x,q.y,.003+(1-p.life/p.max)*.008,0,Math.PI*2);ctx.fill();}ctx.globalAlpha=1;}
  function loop(now){const dt=Math.min(.05,(now-last)/1000||0);last=now;update(dt);draw();requestAnimationFrame(loop);}
  setup();window.addEventListener('resize',resize);resize();requestAnimationFrame(loop);
})();

