import { createRequire } from 'node:module';
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');
const browser = await chromium.launch({headless:true});
const page = await browser.newPage({viewport:{width:1440,height:900}});
const errors=[];
page.on('pageerror', e=>errors.push(e.message));
await page.goto('http://localhost:3000');
await page.locator('[data-faction="china"]').click();
await page.locator('#start-btn').click();
await page.waitForTimeout(300);
const battlefield=page.locator('#battlefield');
const box=await battlefield.boundingBox();
await page.locator('[data-tab="structures"]').click();
await page.locator('[data-build="barracks"]').click();
await battlefield.click({position:{x:box.width*.31,y:box.height*.28}});
await page.waitForTimeout(100);
const barracksToast=await page.locator('#toast').textContent();
const fundsAfterBarracks=await page.locator('#credits').textContent();
await page.locator('[data-tab="units"]').click();
const infantryEnabled=await page.locator('[data-build="infantry"]').isEnabled();
await page.locator('[data-build="infantry"]').click();
await page.waitForTimeout(100);
const army=await page.locator('#army-count').textContent();
const faction=await page.locator('#faction-label').textContent();
await page.screenshot({path:'/tmp/opencode/frontline-gameplay.png'});
console.log(JSON.stringify({faction,barracksToast,fundsAfterBarracks,infantryEnabled,army,errors},null,2));
await browser.close();

