import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.169.0/build/three.module.js';

export function createBattlefield(canvas) {
  const renderer = new THREE.WebGLRenderer({ canvas, antialias: true, alpha: false });
  renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 1.6));
  renderer.shadowMap.enabled = true;
  renderer.shadowMap.type = THREE.PCFSoftShadowMap;
  renderer.outputColorSpace = THREE.SRGBColorSpace;
  renderer.toneMapping = THREE.ACESFilmicToneMapping;
  renderer.toneMappingExposure = 1.15;

  const scene = new THREE.Scene();
  scene.background = new THREE.Color('#a69a70');
  scene.fog = new THREE.Fog('#a69a70', 110, 220);
  const camera = new THREE.OrthographicCamera(-50, 50, 50, -50, 0.1, 300);
  camera.position.set(0, 115, 0.01);
  camera.lookAt(0, 0, 0);
  scene.add(new THREE.HemisphereLight('#e2e8cd', '#4b4937', 2.25));
  const sun = new THREE.DirectionalLight('#fff0d0', 3.2);
  sun.position.set(-35, 75, -28);
  sun.castShadow = true;
  sun.shadow.mapSize.set(1024, 1024);
  sun.shadow.camera.left = -75; sun.shadow.camera.right = 75;
  sun.shadow.camera.top = 75; sun.shadow.camera.bottom = -75;
  sun.shadow.bias = -0.0003;
  scene.add(sun);

  const mat = (color, roughness = 0.86, metalness = 0.04) => new THREE.MeshStandardMaterial({ color, roughness, metalness });
  const groundMat = new THREE.MeshStandardMaterial({ map: makeTerrainTexture(), roughness: 1 });
  const ground = new THREE.Mesh(new THREE.PlaneGeometry(100, 100), groundMat);
  ground.rotation.x = -Math.PI / 2; ground.position.y = -0.2; ground.receiveShadow = true; scene.add(ground);
  const terrainGroup = new THREE.Group(); scene.add(terrainGroup);
  buildTerrain(terrainGroup, mat);

  const entityRoot = new THREE.Group(); scene.add(entityRoot);
  const entities = new Map();
  const transientRoot = new THREE.Group(); scene.add(transientRoot);
  let transientKey = '';

  function resize() {
    const w = Math.max(1, canvas.clientWidth), h = Math.max(1, canvas.clientHeight);
    renderer.setSize(w, h, false);
    const aspect = w / h, zoom = currentZoom;
    camera.left = -50 * aspect / zoom; camera.right = 50 * aspect / zoom;
    camera.top = 50 / zoom; camera.bottom = -50 / zoom;
    camera.updateProjectionMatrix();
  }
  let currentZoom = 1;

  function position(obj, x, y, height = 0) {
    obj.position.set((x - 0.5) * 100 * (canvas.clientWidth / Math.max(1, canvas.clientHeight)), height, (y - 0.5) * 100);
  }
  function teamColor(entity, faction) {
    if (entity.team === 'red') return '#b64d3c';
    return ({ usa: '#658eae', china: '#c34835', russia: '#788f5c' })[faction] || '#658eae';
  }
  function metal(color) { return mat(color, 0.48, 0.46); }
  function box(group, name, size, material, pos, rotation) {
    const mesh = new THREE.Mesh(new THREE.BoxGeometry(...size), material);
    mesh.name = name; mesh.position.set(...pos);
    if (rotation) mesh.rotation.set(...rotation);
    mesh.castShadow = true; mesh.receiveShadow = true; group.add(mesh); return mesh;
  }
  function cylinder(group, radiusTop, radiusBottom, height, material, pos, segments = 12) {
    const mesh = new THREE.Mesh(new THREE.CylinderGeometry(radiusTop, radiusBottom, height, segments), material);
    mesh.position.set(...pos); mesh.castShadow = true; mesh.receiveShadow = true; group.add(mesh); return mesh;
  }
  function cone(group, radius, height, material, pos, segments = 5) {
    const mesh = new THREE.Mesh(new THREE.ConeGeometry(radius, height, segments), material);
    mesh.position.set(...pos); mesh.castShadow = true; group.add(mesh); return mesh;
  }
  function buildEntity(entity, faction) {
    const root = new THREE.Group(); root.userData.id = entity.id;
    const tint = teamColor(entity, faction), team = mat(tint), light = mat(entity.team === 'red' ? '#e87950' : faction === 'china' ? '#f1b84e' : '#c9d4c0');
    const armor = mat('#44473f'), dark = mat('#292d29'), concrete = mat('#77796b'), glass = new THREE.MeshStandardMaterial({ color: '#91b5bd', roughness: 0.28, metalness: 0.2, emissive: '#21383d', emissiveIntensity: 0.25 });
    const s = entity.size ? Math.max(1.7, entity.size / Math.max(1, canvas.clientHeight) * 100) : Math.max(1.25, entity.radius / Math.max(1, canvas.clientHeight) * 180);
    const groundRing = new THREE.Mesh(new THREE.RingGeometry(s * 0.9, s * 1.08, 32), new THREE.MeshBasicMaterial({ color: tint, transparent: true, opacity: 0.42, side: THREE.DoubleSide, depthWrite: false }));
    groundRing.rotation.x = -Math.PI / 2; groundRing.position.y = 0.045; root.add(groundRing);
    const model = new THREE.Group(); root.add(model);
    if (entity.kind === 'hq') {
      box(model, 'reinforced foundation', [s * 2.7, .45, s * 2.3], dark, [0, .34, 0]);
      box(model, 'command center', [s * 2.15, s * .75, s * 1.65], concrete, [0, s * .48, 0]);
      box(model, 'command roof', [s * 1.48, s * .58, s * 1.34], team, [s * .05, s * 1.08, -s * .04]);
      box(model, 'communications wing', [s * .56, s * .52, s * .93], armor, [-s * .69, s * .96, -s * .1]);
      box(model, 'command windows', [s * 1.06, s * .25, .1], glass, [s * .02, s * .66, s * .84]);
      box(model, 'entry ramp', [s * .55, .28, s * .58], concrete, [s * .66, .18, s * 1.02]);
      cylinder(model, s * .045, s * .045, s * 1.1, dark, [-s * .65, s * 1.42, -s * .1], 8);
      cylinder(model, s * .12, s * .12, .12, light, [-s * .65, s * 1.98, -s * .1], 12);
      box(model, 'faction stripe', [s * 1.2, .08, .08], light, [0, s * 1.1, s * .85]);
    } else if (entity.kind === 'refinery') {
      box(model, 'industrial pad', [s * 2.65, .35, s * 2.15], dark, [0, .25, 0]);
      box(model, 'refinery hall', [s * 1.5, s * .86, s * 1.48], concrete, [-s * .34, s * .48, 0]);
      box(model, 'red steel roof', [s * 1.62, .18, s * 1.6], team, [-s * .34, s * .98, 0]);
      for (let i = 0; i < 3; i++) {
        cylinder(model, s * .25, s * .29, s * 1.04, metal(i === 1 ? '#a49a79' : '#868879'), [s * (.48 + i * .43), s * .67, -s * .26]);
        cylinder(model, s * .25, s * .25, .13, light, [s * (.48 + i * .43), s * 1.22, -s * .26]);
      }
      box(model, 'loading dock', [s * .78, s * .28, s * .5], armor, [s * .63, s * .3, s * .77]);
      const belt = box(model, 'ore conveyor', [s * .24, .12, s * 1.65], dark, [s * 1.04, s * .38, s * .72]); belt.rotation.x = -.3;
      for (let i = 0; i < 2; i++) cylinder(model, .045, .045, s * .55, dark, [s * (1.01 + i * .15), s * .25, s * (.2 + i * .72)], 8);
    } else if (entity.kind === 'power') {
      box(model, 'generator plinth', [s * 2.1, .34, s * 1.75], dark, [0, .22, 0]);
      box(model, 'generator', [s * 1.4, s * .78, s * 1.22], concrete, [0, s * .47, 0]);
