    for (let i = 0; i < 18; i++) { ctx.strokeStyle = i % 2 ? '#bcb08020' : '#343d2c20'; ctx.lineWidth = 9 + Math.random() * 16; ctx.beginPath(); ctx.moveTo(-20, i * 31); ctx.bezierCurveTo(120, i * 31 - 24, 320, i * 31 + 48, 540, i * 31 - 12); ctx.stroke(); }
